# Let's construct a bipartite graph with A = {0, 1, 2} and B = {3, 4, 5, 6, 7, 8, 9, 10}
# Every vertex in B is connected to all vertices in A.
# This gives degree 3 for all vertices in B.
# For vertices in A, they are connected to all 8 vertices in B, so degree 8.
# This satisfies delta(G) >= 3.
# Let's check the fixed edges:
# (1, 10), (0, 4), (0, 8), (2, 9)
# 1 in A, 10 in B -> (1, 10) is in K_{3,8}
# 0 in A, 4 in B -> (0, 4) is in K_{3,8}
# 0 in A, 8 in B -> (0, 8) is in K_{3,8}
# 2 in A, 9 in B -> (2, 9) is in K_{3,8}

edges = []
A = [0, 1, 2]
B = [3, 4, 5, 6, 7, 8, 9, 10]
for a in A:
    for b in B:
        edges.append((a, b))

# Verify the fixed edges are in the list
fixed_edges = [(1, 10), (0, 4), (0, 8), (2, 9)]
for edge in fixed_edges:
    if edge not in edges:
        print(f"Edge {edge} not in edges")

# Verify delta(G) >= 3
degrees = {i: 0 for i in range(11)}
for u, v in edges:
    degrees[u] += 1
    degrees[v] += 1

print(f"Degrees: {degrees}")
print(f"Min degree: {min(degrees.values())}")
print(f"Edges: {edges}")
